5: namespace LinuxPDF
6: {
7:     class Program
8:     {
9:         static void Main(string[] args)
10:         {
11:             // Default to the local script-based "exorcism" approach
12:             bool runLocalScript = true;
13:             string isoPath = null;
14:             string mode = "exorcism"; // your existing default
15:             string targetPath = Environment.GetEnvironmentVariable("TEMP");
16:             bool offline = false;
17:             bool log = false;
18: 
19:             // Parse arguments
20:             // e.g.  --boot=ghost_boot.iso --mode=bind --target="C:\some\path" --offline --log
21:             foreach (var arg in args)
22:             {
23:                 if (arg.StartsWith("--boot="))
24:                 {
25:                     isoPath = arg.Substring("--boot=".Length);
26:                     runLocalScript = false;
27:                 }
28:                 else if (arg.StartsWith("--mode="))
29:                 {
30:                     mode = arg.Substring("--mode=".Length);
31:                 }
32:                 else if (arg.StartsWith("--target="))
33:                 {
34:                     targetPath = arg.Substring("--target=".Length);
35:                 }
36:                 else if (arg == "--offline") offline = true;
37:                 else if (arg == "--log") log = true;
38:             }
39: 
40:             // If we have an ISO path, attempt to run QEMU
41:             if (!string.IsNullOrEmpty(isoPath))
42:             {
43:                 // Full path to QEMU exe, placed next to LinuxPDF.exe
44:                 string baseDir = AppContext.BaseDirectory;
45:                 string qemuExe = Path.Combine(baseDir, "qemu-system-x86_64.exe");
46: 
47:                 if (!File.Exists(qemuExe))
48:                 {
49:                     Console.Error.WriteLine("[LinuxPDF] QEMU exe not found, can't boot ISO. Will fallback to local script.");
50:                     runLocalScript = true;
51:                 }
52:                 else
53:                 {
54:                     // Also check if isoPath is relative
55:                     if (!Path.IsPathRooted(isoPath))
56:                         isoPath = Path.Combine(baseDir, isoPath);
57: 
58:                     if (!File.Exists(isoPath))
59:                     {
60:                         Console.Error.WriteLine($"[LinuxPDF] ISO file not found: {isoPath}. Fallback to local script.");
61:                         runLocalScript = true;
62:                     }
63:                     else
64:                     {
65:                         // We have qemu + iso => run the VM
66:                         string qemuArgs = $"-m 512 -cdrom \"{isoPath}\" -boot d -enable-kvm";
67:                         Console.WriteLine($"[LinuxPDF] Launching QEMU with: {qemuArgs}");
68: 
69:                         var psi = new ProcessStartInfo(qemuExe, qemuArgs)
70:                         {
71:                             UseShellExecute = false,
72:                             RedirectStandardOutput = true,
73:                             RedirectStandardError = true,
74:                             CreateNoWindow = false
75:                         };
76: 
77:                         using (var proc = Process.Start(psi))
78:                         {
79:                             proc.BeginOutputReadLine();
80:                             proc.BeginErrorReadLine();
81:                             proc.WaitForExit();
82:                         }
83: 
84:                         Console.WriteLine("[LinuxPDF] QEMU run complete.");
85:                     }
86:                 }
87:             }
88: 
89:             // If no ISO or QEMU not found => fallback to local script
90:             if (runLocalScript)
91:             {
92:                 // same logic you had before, e.g. call LinuxPDF_Runtime.ps1
93:                 string baseDir = AppContext.BaseDirectory;
94:                 string psPath = Path.Combine(baseDir, "LinuxPDF_Runtime.ps1");
95:                 string psCommand = $"-ExecutionPolicy Bypass -NoLogo -NoProfile -File \"{psPath}\" -Mode {mode} -Path \"{targetPath}\"";
96: 
97:                 if (offline) psCommand += " -Offline";
98:                 if (log) psCommand += " -Log";
99: 
100:                 Console.WriteLine($"[LinuxPDF] Fallback to local script with mode='{mode}', path='{targetPath}', offline={offline}, log={log}");
101: 
102:                 Process.Start("powershell.exe", psCommand);
103:             }
104:         }
105:     }
106: }

1: # ExorcistMode.ps1 - Windows Ghost Whisper Exorcism Protocol
2: # Modes: Anoint (Scan), Bind (Contain), Cleanse (Purge)
3: # Integrates with GhostWhisper logging and optional LinuxPDF sandboxing
4: 
5: param (
