# BinaryPulsar.ps1
# GhostWhisper Binary Analysis & Packet Reconstruction Module
# PowerShell wrapper for Binary Pulsar network analysis capabilities

$Script:PulsarVersion = "1.0.0"
$Script:PulsarActive = $false
$Script:PacketBuffer = [System.Collections.ArrayList]::new()
$Script:FragmentStore = @{}
$Script:EntropyMap = @{}

# ============================================================================
# BINARY ANALYSIS FUNCTIONS
# ============================================================================

function ConvertFrom-HexString {
    param([string]$HexString)

    $HexString = $HexString -replace '\s', ''
    $bytes = [byte[]]::new($HexString.Length / 2)

    for ($i = 0; $i -lt $bytes.Length; $i++) {
        $bytes[$i] = [Convert]::ToByte($HexString.Substring($i * 2, 2), 16)
    }

    return $bytes
}

function Get-BinaryEntropy {
    param([byte[]]$Data)

    if ($Data.Length -eq 0) { return 0 }

    $frequency = @{}
    foreach ($byte in $Data) {
        if ($frequency.ContainsKey($byte)) {
            $frequency[$byte]++
        } else {
            $frequency[$byte] = 1
        }
    }

    $entropy = 0.0
    $total = $Data.Length

    foreach ($count in $frequency.Values) {
        $probability = $count / $total
        if ($probability -gt 0) {
            $entropy -= $probability * [Math]::Log($probability, 2)
        }
    }

    return [Math]::Round($entropy, 4)
}

function Get-BinaryFileType {
    param([byte[]]$Data)

    if ($Data.Length -lt 4) { return "Unknown" }

    $magic = [BitConverter]::ToString($Data[0..3]) -replace '-', ''

    $signatures = @{
        "4D5A"     = "PE/EXE"
        "7F454C46" = "ELF"
        "504B0304" = "ZIP/JAR"
        "25504446" = "PDF"
        "89504E47" = "PNG"
        "FFD8FF"   = "JPEG"
        "47494638" = "GIF"
        "52617221" = "RAR"
        "1F8B08"   = "GZIP"
        "CAFEBABE" = "Java Class"
        "FEEDFACE" = "Mach-O 32"
        "FEEDFACF" = "Mach-O 64"
        "D0CF11E0" = "MS Office"
    }

    foreach ($sig in $signatures.Keys) {
        if ($magic.StartsWith($sig)) {
            return $signatures[$sig]
        }
    }

    return "Unknown"
}

function Invoke-BinaryAnalysis {
    <#
    .SYNOPSIS
    Analyzes binary data for structure, entropy, and embedded payloads.

    .PARAMETER Data
    Binary data as byte array, hex string, or base64 string.

    .PARAMETER Format
    Input format: Raw, Hex, Base64

    .EXAMPLE
    Invoke-BinaryAnalysis -Data "TVqQAAMAAAA..." -Format Base64
    #>
    param(
        [Parameter(Mandatory = $true)]
        $Data,

        [ValidateSet("Raw", "Hex", "Base64")]
        [string]$Format = "Raw"
    )

    # Convert to byte array
    $bytes = switch ($Format) {
        "Hex" { ConvertFrom-HexString -HexString $Data }
        "Base64" { [Convert]::FromBase64String($Data) }
        "Raw" { 
            if ($Data -is [byte[]]) { $Data }
            else { [System.Text.Encoding]::UTF8.GetBytes($Data) }
        }
    }

    $result = [PSCustomObject]@{
        Size          = $bytes.Length
        FileType      = Get-BinaryFileType -Data $bytes
        Entropy       = Get-BinaryEntropy -Data $bytes
        Sections      = @()
        Payloads      = @()
        Strings       = @()
        SuspiciousPatterns = @()
    }

    # Analyze sections by entropy changes
    $windowSize = [Math]::Min(256, $bytes.Length / 4)
    if ($windowSize -gt 16) {
        for ($i = 0; $i -lt $bytes.Length - $windowSize; $i += $windowSize) {
            $window = $bytes[$i..($i + $windowSize - 1)]
            $windowEntropy = Get-BinaryEntropy -Data $window

            $result.Sections += [PSCustomObject]@{
                Offset  = $i
                Size    = $windowSize
                Entropy = $windowEntropy
            }
        }
    }

    # Extract printable strings
    $stringBuilder = [System.Text.StringBuilder]::new()
    $currentString = ""

    foreach ($byte in $bytes) {
        if ($byte -ge 32 -and $byte -le 126) {
            $currentString += [char]$byte
        } else {
            if ($currentString.Length -ge 4) {
                $result.Strings += $currentString
            }
            $currentString = ""
        }
    }
    if ($currentString.Length -ge 4) {
        $result.Strings += $currentString
    }

    # Look for base64 encoded payloads in strings
    foreach ($str in $result.Strings) {
        if ($str.Length -ge 20 -and $str -match '^[A-Za-z0-9+/=]+$') {
            try {
                $decoded = [Convert]::FromBase64String($str)
                if ($decoded.Length -gt 0) {
                    $result.Payloads += [PSCustomObject]@{
                        Type    = "Base64"
                        Offset  = 0
                        Data    = $str
                        Preview = [System.Text.Encoding]::UTF8.GetString($decoded[0..([Math]::Min(50, $decoded.Length - 1))])
                    }
                }
            } catch { }
        }
    }

    # Look for suspicious patterns
    $suspiciousPatterns = @(
        @{ Pattern = "cmd\.exe"; Description = "Command shell reference" },
        @{ Pattern = "powershell"; Description = "PowerShell reference" },
        @{ Pattern = "WScript"; Description = "Windows Script Host" },
        @{ Pattern = "CreateRemoteThread"; Description = "Remote thread injection" },
        @{ Pattern = "VirtualAlloc"; Description = "Memory allocation" },
        @{ Pattern = "LoadLibrary"; Description = "DLL loading" },
        @{ Pattern = "GetProcAddress"; Description = "API resolution" },
        @{ Pattern = "NtCreateThread"; Description = "Native thread creation" },
        @{ Pattern = "ShellExecute"; Description = "Shell execution" },
        @{ Pattern = "/dev/tcp"; Description = "Bash reverse shell" },
        @{ Pattern = "nc -e"; Description = "Netcat shell" }
    )

    $text = [System.Text.Encoding]::UTF8.GetString($bytes)
    foreach ($pattern in $suspiciousPatterns) {
        if ($text -match $pattern.Pattern) {
            $result.SuspiciousPatterns += $pattern.Description
        }
    }

    return $result
}

# ============================================================================
# PACKET ANALYSIS FUNCTIONS
# ============================================================================

function Add-PulsarFragment {
    <#
    .SYNOPSIS
    Adds a fragment to the Binary Pulsar reconstruction buffer.

    .PARAMETER Index
    Fragment sequence number.

    .PARAMETER Payload
    Base64 encoded fragment payload.
    #>
    param(
        [Parameter(Mandatory = $true)]
        [int]$Index,

        [Parameter(Mandatory = $true)]
        [string]$Payload
    )

    if (-not $Script:FragmentStore.ContainsKey($Index)) {
        $Script:FragmentStore[$Index] = $Payload
        Write-Host "[PULSAR] Fragment $Index accepted (Total: $($Script:FragmentStore.Count))" -ForegroundColor Cyan
    }
}

function Invoke-PacketAnalysis {
    <#
    .SYNOPSIS
    Analyzes network packet data for covert channels.

    .PARAMETER PacketData
    Packet data in format: sequence|data|protocol

    .EXAMPLE
    Invoke-PacketAnalysis -PacketData "123|YWJjZGU=|IPv4"
    #>
    param(
        [Parameter(Mandatory = $true)]
        [string]$PacketData
    )

    $fields = $PacketData -split '\|'

    if ($fields.Count -lt 3) {
        Write-Warning "[PULSAR] Invalid packet format"
        return $null
    }

    $packet = [PSCustomObject]@{
        Sequence  = [int]$fields[0]
        Data      = $fields[1]
        Protocol  = $fields[2]
        Timestamp = Get-Date
    }

    [void]$Script:PacketBuffer.Add($packet)

    # Attempt reconstruction if buffer has enough packets
    if ($Script:PacketBuffer.Count -ge 5) {
        $result = Invoke-PacketReconstruction
        return $result
    }

    return $packet
}

function Invoke-PacketReconstruction {
    <#
    .SYNOPSIS
    Attempts to reconstruct payload from packet buffer using entropy-based analysis.
    #>

    # Sort by sequence
    $sorted = $Script:PacketBuffer | Sort-Object Sequence

    # Identify gaps (packet loss pattern)
    $gaps = @()
    for ($i = 1; $i -lt $sorted.Count; $i++) {
        $expectedSeq = $sorted[$i - 1].Sequence + 1
        if ($sorted[$i].Sequence -gt $expectedSeq) {
            $gaps += [PSCustomObject]@{
                Start = $expectedSeq
                End   = $sorted[$i].Sequence - 1
                Size  = $sorted[$i].Sequence - $expectedSeq
            }
        }
    }

    # Calculate entropy from gap pattern
    if ($gaps.Count -gt 0) {
        $entropyValue = ($gaps | Measure-Object -Property Size -Sum).Sum % 1000
        $fragmentIndex = $entropyValue % 100

        # Extract payload from buffer
        $payload = ($sorted | ForEach-Object { $_.Data }) -join ''

        if ($payload.Length -gt 0) {
            Add-PulsarFragment -Index $fragmentIndex -Payload $payload
            Write-Host "[PULSAR] Extracted fragment $fragmentIndex from packets (entropy: $entropyValue)" -ForegroundColor Green
        }
    }

    # Trim buffer
    if ($Script:PacketBuffer.Count -gt 20) {
        $Script:PacketBuffer = [System.Collections.ArrayList]::new($Script:PacketBuffer[-10..-1])
    }

    return [PSCustomObject]@{
        BufferSize  = $Script:PacketBuffer.Count
        GapsFound   = $gaps.Count
        Fragments   = $Script:FragmentStore.Count
    }
}

function Invoke-FragmentAssembly {
    <#
    .SYNOPSIS
    Assembles all collected fragments into final payload.
    #>

    if ($Script:FragmentStore.Count -eq 0) {
        Write-Warning "[PULSAR] No fragments to assemble"
        return $null
    }

    # Sort by index and assemble
    $sortedKeys = $Script:FragmentStore.Keys | Sort-Object
    $assembled = ($sortedKeys | ForEach-Object { $Script:FragmentStore[$_] }) -join ''

    Write-Host "[PULSAR] Assembled $($Script:FragmentStore.Count) fragments" -ForegroundColor Green

    try {
        $decoded = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($assembled))

        return [PSCustomObject]@{
            RawAssembly    = $assembled
            DecodedPayload = $decoded
            FragmentCount  = $Script:FragmentStore.Count
        }
    }
    catch {
        return [PSCustomObject]@{
            RawAssembly   = $assembled
            Error         = $_.Exception.Message
            FragmentCount = $Script:FragmentStore.Count
        }
    }
}

# ============================================================================
# NETWORK CAPTURE SIMULATION
# ============================================================================

function Start-PulsarCapture {
    <#
    .SYNOPSIS
    Starts the Binary Pulsar packet capture simulation.

    .PARAMETER Duration
    Capture duration in seconds.

    .PARAMETER Interval
    Packet generation interval in milliseconds.
    #>
    param(
        [int]$Duration = 60,
        [int]$Interval = 1000
    )

    if ($Script:PulsarActive) {
        Write-Warning "[PULSAR] Capture already active"
        return
    }

    $Script:PulsarActive = $true
