function Invoke-BinaryFileScan {
    <#
    .SYNOPSIS
    Scans a binary file for malicious patterns and embedded payloads.

    .PARAMETER Path
    Path to the file to analyze.

    .EXAMPLE
    Invoke-BinaryFileScan -Path "C:\suspicious.exe"
    #>
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    if (-not (Test-Path $Path)) {
        Write-Error "File not found: $Path"
        return
    }

    Write-Host "[PULSAR] Analyzing: $Path" -ForegroundColor Cyan

    $bytes = [System.IO.File]::ReadAllBytes($Path)
    $result = Invoke-BinaryAnalysis -Data $bytes -Format Raw

    $result | Add-Member -NotePropertyName FileName -NotePropertyValue (Split-Path $Path -Leaf)
    $result | Add-Member -NotePropertyName FilePath -NotePropertyValue $Path
    $result | Add-Member -NotePropertyName FileHash -NotePropertyValue (Get-FileHash -Path $Path -Algorithm SHA256).Hash

    # Detailed report
    Write-Host ""
    Write-Host "═══════════════════════════════════════════════════════════" -ForegroundColor Cyan
    Write-Host "  BINARY PULSAR ANALYSIS REPORT" -ForegroundColor Cyan
    Write-Host "═══════════════════════════════════════════════════════════" -ForegroundColor Cyan
    Write-Host ""
    Write-Host "  File:     $($result.FileName)" -ForegroundColor White
    Write-Host "  Size:     $($result.Size) bytes" -ForegroundColor White
    Write-Host "  Type:     $($result.FileType)" -ForegroundColor White
    Write-Host "  Entropy:  $($result.Entropy) $(if($result.Entropy -gt 7.5){'[HIGH - Possible encryption/packing]'})" -ForegroundColor $(if($result.Entropy -gt 7.5){'Red'}else{'Green'})
    Write-Host "  SHA256:   $($result.FileHash)" -ForegroundColor Gray
    Write-Host ""

    if ($result.SuspiciousPatterns.Count -gt 0) {
        Write-Host "  ⚠️  SUSPICIOUS PATTERNS DETECTED:" -ForegroundColor Red
        foreach ($pattern in $result.SuspiciousPatterns) {
            Write-Host "      - $pattern" -ForegroundColor Yellow
        }
        Write-Host ""
    }

    if ($result.Payloads.Count -gt 0) {
        Write-Host "  📦 Embedded Payloads Found: $($result.Payloads.Count)" -ForegroundColor Yellow
        foreach ($payload in $result.Payloads) {
            Write-Host "      Type: $($payload.Type)" -ForegroundColor Gray
            Write-Host "      Preview: $($payload.Preview.Substring(0, [Math]::Min(40, $payload.Preview.Length)))..." -ForegroundColor Gray
        }
        Write-Host ""
    }

    Write-Host "  Strings Found: $($result.Strings.Count)" -ForegroundColor White
    Write-Host "  Sections:      $($result.Sections.Count)" -ForegroundColor White
    Write-Host ""
    Write-Host "═══════════════════════════════════════════════════════════" -ForegroundColor Cyan

    return $result
}

function Invoke-DirectoryScan {
    <#
    .SYNOPSIS
    Scans a directory for suspicious binary files.

    .PARAMETER Path
    Directory path to scan.

    .PARAMETER Extensions
    File extensions to scan.

    .EXAMPLE
    Invoke-DirectoryScan -Path "C:\Users\Public" -Extensions @(".exe", ".dll")
    #>
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [string[]]$Extensions = @(".exe", ".dll", ".sys", ".bin", ".scr"),

        [switch]$Recurse
    )

    if (-not (Test-Path $Path)) {
        Write-Error "Directory not found: $Path"
        return
    }

    Write-Host "[PULSAR] Scanning directory: $Path" -ForegroundColor Cyan

    $files = Get-ChildItem -Path $Path -Recurse:$Recurse -File -ErrorAction SilentlyContinue |
             Where-Object { $_.Extension -in $Extensions }

    Write-Host "[PULSAR] Found $($files.Count) files to analyze" -ForegroundColor Gray

    $results = @()
    $suspicious = @()

    foreach ($file in $files) {
        try {
            $result = Invoke-BinaryFileScan -Path $file.FullName
            $results += $result

            if ($result.SuspiciousPatterns.Count -gt 0 -or $result.Entropy -gt 7.5) {
                $suspicious += $result
            }
        }
        catch {
            Write-Warning "Failed to analyze: $($file.FullName)"
        }
    }

    Write-Host ""
    Write-Host "[PULSAR] Scan complete. Suspicious files: $($suspicious.Count)/$($files.Count)" -ForegroundColor $(if($suspicious.Count -gt 0){'Yellow'}else{'Green'})

    return [PSCustomObject]@{
        TotalScanned  = $files.Count
        SuspiciousCount = $suspicious.Count
        Results       = $results
        Suspicious    = $suspicious
    }
}

