# BinaryPulsar.ps1
# GhostWhisper Binary Analysis & Packet Reconstruction Module
# PowerShell wrapper for Binary Pulsar network analysis capabilities

$Script:PulsarVersion = "1.0.0"
$Script:PulsarActive = $false
$Script:PacketBuffer = [System.Collections.ArrayList]::new()
$Script:FragmentStore = @{}
$Script:EntropyMap = @{}

# ============================================================================
# BINARY ANALYSIS FUNCTIONS
# ============================================================================

function ConvertFrom-HexString {
    param([string]$HexString)

    $HexString = $HexString -replace '\s', ''
    $bytes = [byte[]]::new($HexString.Length / 2)

    for ($i = 0; $i -lt $bytes.Length; $i++) {
        $bytes[$i] = [Convert]::ToByte($HexString.Substring($i * 2, 2), 16)
    }

    return $bytes
}

function Get-BinaryEntropy {
    param([byte[]]$Data)

    if ($Data.Length -eq 0) { return 0 }

    $frequency = @{}
    foreach ($byte in $Data) {
        if ($frequency.ContainsKey($byte)) {
            $frequency[$byte]++
        } else {
            $frequency[$byte] = 1
        }
    }

    $entropy = 0.0
    $total = $Data.Length

    foreach ($count in $frequency.Values) {
        $probability = $count / $total
        if ($probability -gt 0) {
            $entropy -= $probability * [Math]::Log($probability, 2)
        }
    }

    return [Math]::Round($entropy, 4)
}

function Get-BinaryFileType {
    param([byte[]]$Data)

    if ($Data.Length -lt 4) { return "Unknown" }

    $magic = [BitConverter]::ToString($Data[0..3]) -replace '-', ''

    $signatures = @{
        "4D5A"     = "PE/EXE"
        "7F454C46" = "ELF"
        "504B0304" = "ZIP/JAR"
        "25504446" = "PDF"
        "89504E47" = "PNG"
        "FFD8FF"   = "JPEG"
        "47494638" = "GIF"
        "52617221" = "RAR"
        "1F8B08"   = "GZIP"
        "CAFEBABE" = "Java Class"
        "FEEDFACE" = "Mach-O 32"
        "FEEDFACF" = "Mach-O 64"
        "D0CF11E0" = "MS Office"
    }

    foreach ($sig in $signatures.Keys) {
        if ($magic.StartsWith($sig)) {
            return $signatures[$sig]
        }
    }

    return "Unknown"
}

function Invoke-BinaryAnalysis {
    <#
    .SYNOPSIS
    Analyzes binary data for structure, entropy, and embedded payloads.

    .PARAMETER Data
    Binary data as byte array, hex string, or base64 string.

    .PARAMETER Format
    Input format: Raw, Hex, Base64

    .EXAMPLE
    Invoke-BinaryAnalysis -Data "TVqQAAMAAAA..." -Format Base64
    #>
    param(
        [Parameter(Mandatory = $true)]
        $Data,

        [ValidateSet("Raw", "Hex", "Base64")]
        [string]$Format = "Raw"
    )

    # Convert to byte array
    $bytes = switch ($Format) {
        "Hex" { ConvertFrom-HexString -HexString $Data }
        "Base64" { [Convert]::FromBase64String($Data) }
        "Raw" { 
            if ($Data -is [byte[]]) { $Data }
            else { [System.Text.Encoding]::UTF8.GetBytes($Data) }
        }
    }

    $result = [PSCustomObject]@{
        Size          = $bytes.Length
        FileType      = Get-BinaryFileType -Data $bytes
        Entropy       = Get-BinaryEntropy -Data $bytes
        Sections      = @()
        Payloads      = @()
        Strings       = @()
        SuspiciousPatterns = @()
    }

    # Analyze sections by entropy changes
    $windowSize = [Math]::Min(256, $bytes.Length / 4)
    if ($windowSize -gt 16) {
        for ($i = 0; $i -lt $bytes.Length - $windowSize; $i += $windowSize) {
            $window = $bytes[$i..($i + $windowSize - 1)]
            $windowEntropy = Get-BinaryEntropy -Data $window

            $result.Sections += [PSCustomObject]@{
                Offset  = $i
                Size    = $windowSize
                Entropy = $windowEntropy
            }
        }
    }

    # Extract printable strings
    $stringBuilder = [System.Text.StringBuilder]::new()
    $currentString = ""

    foreach ($byte in $bytes) {
        if ($byte -ge 32 -and $byte -le 126) {
            $currentString += [char]$byte
        } else {
            if ($currentString.Length -ge 4) {
                $result.Strings += $currentString
            }
            $currentString = ""
        }
    }
    if ($currentString.Length -ge 4) {
        $result.Strings += $currentString
    }

    # Look for base64 encoded payloads in strings
    foreach ($str in $result.Strings) {
        if ($str.Length -ge 20 -and $str -match '^[A-Za-z0-9+/=]+$') {
            try {
                $decoded = [Convert]::FromBase64String($str)
                if ($decoded.Length -gt 0) {
                    $result.Payloads += [PSCustomObject]@{
                        Type    = "Base64"
                        Offset  = 0
                        Data    = $str
                        Preview = [System.Text.Encoding]::UTF8.GetString($decoded[0..([Math]::Min(50, $decoded.Length - 1))])
                    }
                }
            } catch { }
        }
    }

    # Look for suspicious patterns
    $suspiciousPatterns = @(
        @{ Pattern = "cmd\.exe"; Description = "Command shell reference" },
        @{ Pattern = "powershell"; Description = "PowerShell reference" },
        @{ Pattern = "WScript"; Description = "Windows Script Host" },
        @{ Pattern = "CreateRemoteThread"; Description = "Remote thread injection" },
        @{ Pattern = "VirtualAlloc"; Description = "Memory allocation" },
        @{ Pattern = "LoadLibrary"; Description = "DLL loading" },
        @{ Pattern = "GetProcAddress"; Description = "API resolution" },
        @{ Pattern = "NtCreateThread"; Description = "Native thread creation" },
        @{ Pattern = "ShellExecute"; Description = "Shell execution" },
        @{ Pattern = "/dev/tcp"; Description = "Bash reverse shell" },
        @{ Pattern = "nc -e"; Description = "Netcat shell" }
    )

    $text = [System.Text.Encoding]::UTF8.GetString($bytes)
    foreach ($pattern in $suspiciousPatterns) {
        if ($text -match $pattern.Pattern) {
            $result.SuspiciousPatterns += $pattern.Description
        }
    }

    return $result
}

