function Add-PulsarFragment {
    <#
    .SYNOPSIS
    Adds a fragment to the Binary Pulsar reconstruction buffer.

    .PARAMETER Index
    Fragment sequence number.

    .PARAMETER Payload
    Base64 encoded fragment payload.
    #>
    param(
        [Parameter(Mandatory = $true)]
        [int]$Index,

        [Parameter(Mandatory = $true)]
        [string]$Payload
    )

    if (-not $Script:FragmentStore.ContainsKey($Index)) {
        $Script:FragmentStore[$Index] = $Payload
        Write-Host "[PULSAR] Fragment $Index accepted (Total: $($Script:FragmentStore.Count))" -ForegroundColor Cyan
    }
}

function Invoke-PacketAnalysis {
    <#
    .SYNOPSIS
    Analyzes network packet data for covert channels.

    .PARAMETER PacketData
    Packet data in format: sequence|data|protocol

    .EXAMPLE
    Invoke-PacketAnalysis -PacketData "123|YWJjZGU=|IPv4"
    #>
    param(
        [Parameter(Mandatory = $true)]
        [string]$PacketData
    )

    $fields = $PacketData -split '\|'

    if ($fields.Count -lt 3) {
        Write-Warning "[PULSAR] Invalid packet format"
        return $null
    }

    $packet = [PSCustomObject]@{
        Sequence  = [int]$fields[0]
        Data      = $fields[1]
        Protocol  = $fields[2]
        Timestamp = Get-Date
    }

    [void]$Script:PacketBuffer.Add($packet)

    # Attempt reconstruction if buffer has enough packets
    if ($Script:PacketBuffer.Count -ge 5) {
        $result = Invoke-PacketReconstruction
        return $result
    }

    return $packet
}

function Invoke-PacketReconstruction {
    <#
    .SYNOPSIS
    Attempts to reconstruct payload from packet buffer using entropy-based analysis.
    #>

    # Sort by sequence
    $sorted = $Script:PacketBuffer | Sort-Object Sequence

    # Identify gaps (packet loss pattern)
    $gaps = @()
    for ($i = 1; $i -lt $sorted.Count; $i++) {
        $expectedSeq = $sorted[$i - 1].Sequence + 1
        if ($sorted[$i].Sequence -gt $expectedSeq) {
            $gaps += [PSCustomObject]@{
                Start = $expectedSeq
                End   = $sorted[$i].Sequence - 1
                Size  = $sorted[$i].Sequence - $expectedSeq
            }
        }
    }

    # Calculate entropy from gap pattern
    if ($gaps.Count -gt 0) {
        $entropyValue = ($gaps | Measure-Object -Property Size -Sum).Sum % 1000
        $fragmentIndex = $entropyValue % 100

        # Extract payload from buffer
        $payload = ($sorted | ForEach-Object { $_.Data }) -join ''

        if ($payload.Length -gt 0) {
            Add-PulsarFragment -Index $fragmentIndex -Payload $payload
            Write-Host "[PULSAR] Extracted fragment $fragmentIndex from packets (entropy: $entropyValue)" -ForegroundColor Green
        }
    }

    # Trim buffer
    if ($Script:PacketBuffer.Count -gt 20) {
        $Script:PacketBuffer = [System.Collections.ArrayList]::new($Script:PacketBuffer[-10..-1])
    }

    return [PSCustomObject]@{
        BufferSize  = $Script:PacketBuffer.Count
        GapsFound   = $gaps.Count
        Fragments   = $Script:FragmentStore.Count
    }
}

function Invoke-FragmentAssembly {
    <#
    .SYNOPSIS
    Assembles all collected fragments into final payload.
    #>

    if ($Script:FragmentStore.Count -eq 0) {
        Write-Warning "[PULSAR] No fragments to assemble"
        return $null
    }

    # Sort by index and assemble
    $sortedKeys = $Script:FragmentStore.Keys | Sort-Object
    $assembled = ($sortedKeys | ForEach-Object { $Script:FragmentStore[$_] }) -join ''

    Write-Host "[PULSAR] Assembled $($Script:FragmentStore.Count) fragments" -ForegroundColor Green

    try {
        $decoded = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($assembled))

        return [PSCustomObject]@{
            RawAssembly    = $assembled
            DecodedPayload = $decoded
            FragmentCount  = $Script:FragmentStore.Count
        }
    }
    catch {
        return [PSCustomObject]@{
            RawAssembly   = $assembled
            Error         = $_.Exception.Message
            FragmentCount = $Script:FragmentStore.Count
        }
    }
}

